c id, e.g. "cascadia.slowSlipIndex" severity: 'info' | 'watch' | 'warning'; note: string; isPrediction: false; } // packages/contracts/src/events.ts (observed, characterized, never forecast) export interface HazardEvent { id: string; kind: 'seismic' | 'volcanic' | 'tsunami' | 'flood' | 'wildfire' | 'marineHeatwave' | 'hab' | 'weather' | 'spaceWeather' | 'anomaly'; t0: number; status: 'open' | 'ack' | 'resolved'; entityIds: string[]; metricIds: string[]; characterization?: Record<string, unknown>; // magnitudes, locations, with uncertainty isPrediction: false; // hard literal. observed events do not predict. officialSource?: string; // set when this mirrors an issued warning (NWS, ShakeAlert) } // packages/contracts/src/forecasts.ts (the weather exception, predictive on purpose) // Only the atmosphere and hydromet may use this. Solid-earth code must not import it. export interface Forecast { id: string; metricId?: string; hazardKind?: HazardEvent['kind']; issuedAt: number; validStart: number; validEnd: number; leadTimeHours: number; value?: number; // deterministic probability?: number; // 0..1 if probabilistic model: 'HRRR' | 'GFS' | 'ECMWF' | 'WaveWatch3' | 'NWS' | 'surge'; skill?: Record<string, number>; // stated skill, e.g. brier, crps, lead-time skill } // packages/contracts/src/geoproducts.ts (heavy artifacts, R2-backed, DVC-versioned) export interface GeoProduct { id: string; kind: 'dvvMatrix' | 'hvsrCurve' | 'rfStack' | 'rfTimeSeries' | 'tremorCatalog' | 'gnssSeries' | 'noiseCorrelation' | 'radarSweep' | 'forecastGrid' | 'subsurfaceVolume' | 'gnssAcoustic' | 'fishingEffort' | 'sarDetections' | 'sstField'; uri: string; t0: number; t1: number; entityId?: string; uncertainty?: Record<string, number>; method: string; } // packages/contracts/src/layers.ts (what the globe can render) export interface GlobeLayer { id: string; title: string; kind: 'points' | 'primitives' | 'field' | 'volume' |
| 'GFS' | 'ECMWF' | 'WaveWatch3' | 'NWS' | 'surge'; skill?: Record<string, number>; // stated skill, e.g. brier, crps, lead-time skill } // packages/contracts/src/geoproducts.ts (heavy artifacts, R2-backed, DVC-versioned) export interface GeoProduct { id: string; kind: 'dvvMatrix' | 'hvsrCurve' | 'rfStack' | 'rfTimeSeries' | 'tremorCatalog' | 'gnssSeries' | 'noiseCorrelation' | 'radarSweep' | 'forecastGrid' | 'subsurfaceVolume' | 'gnssAcoustic' | 'fishingEffort' | 'sarDetections' | 'sstField'; uri: string; t0: number; t1: number; entityId?: string; uncertainty?: Record<string, number>; method: string; } // packages/contracts/src/layers.ts (what the globe can render) export interface GlobeLayer { id: string; title: string; kind: 'points' | 'primitives' | 'field' | 'volume' | 'video' | 'particles'; visualMode?: 'default' | 'bathyXray' | 'hydrophone' | 'causalWeb'; source: string; }
